/** Pure presentation helpers. Scientific answers are generated by the Python engine. */
export function readState(search, payload) {
  const params = new URLSearchParams(search);
  const questions = new Set(payload.answers.map(a => a.question.id));
  const families = new Set(payload.statements.map(s => s.family));
  const state = {question: params.get('question') || 'release-scope', family: params.get('family') || '',
    q: params.get('q') || '', history: params.get('history') === '1',
    view: params.get('view') === 'cards' ? 'cards' : 'table', selected: params.get('selected') || ''};
  if (state.question !== 'browse' && !questions.has(state.question)) state.question = 'release-scope';
  if (!families.has(state.family)) state.family = '';
  if (!payload.statements.some(s => s.id === state.selected)) state.selected = '';
  return state;
}

export function stateSearch(state) {
  const params = new URLSearchParams();
  if (state.question && state.question !== 'release-scope') params.set('question', state.question);
  for (const key of ['family', 'q', 'selected']) if (state[key]) params.set(key, state[key]);
  if (state.history) params.set('history', '1');
  if (state.view === 'cards') params.set('view', 'cards');
  return params.toString() ? '?' + params.toString() : '';
}

export function selectRows(payload, state) {
  const question = payload.answers.find(a => a.question.id === state.question)?.question;
  const terms = state.q.toLowerCase().trim().split(/\s+/).filter(Boolean);
  return payload.statements.filter(s =>
    (state.history || s.lifecycle === 'current' && s.review_state === 'accepted') &&
    (!state.family || s.family === state.family) &&
    (!question || question.subjects.includes(s.subject) && question.predicates.includes(s.predicate)) &&
    terms.every(term => `${s.text} ${s.scope} ${s.claim_id} ${s.subject_label} ${s.object_label}`.toLowerCase().includes(term))
  ).sort((a,b) => a.claim_id.localeCompare(b.claim_id) || a.revision - b.revision);
}

export function neighborhood(payload, statement) {
  if (!statement) return [];
  const nodes = new Map(); const edges = [];
  const known = new Map(payload.objects.map(o => [o.id,o]));
  const node = (id,label,kind) => {
    if (!nodes.has(id)) nodes.set(id, {data:{id,label,kind}});
  };
  const edge = (from,to,label,evidenceId) => {
    let item=edges.find(e=>e.data.source===from&&e.data.target===to&&e.data.label===label);
    if(!item){item={data:{id:'edge-'+edges.length,source:from,target:to,label,evidence_ids:[]}};edges.push(item);}
    if(evidenceId&&!item.data.evidence_ids.includes(evidenceId))item.data.evidence_ids.push(evidenceId);
  };
  node(statement.subject,statement.subject_label, known.get(statement.subject)?.kind || 'evaluation');
  node(statement.id,`Assertion r${statement.revision}\n${statement.review_state} · ${statement.lifecycle}`,'assertion');
  node(statement.object,statement.object_label, known.get(statement.object)?.kind || 'object');
  edge(statement.subject,statement.id,'subject');
  edge(statement.id,statement.object,statement.predicate.replaceAll('_',' '));
  for (const evidence of statement.evidence) {
    node(evidence.source.id, evidence.source.label, 'source');
    edge(evidence.source.id,statement.id,evidence.stance + ' · ' + evidence.scope,evidence.id);
  }
  for (const evaluation of statement.evaluations) {
    node(evaluation.id,evaluation.label,'evaluation');
    if (evaluation.id !== statement.subject) edge(evaluation.id,statement.id,'evaluation context');
    node(evaluation.configuration.id,evaluation.configuration.label,'configuration');
    edge(evaluation.id,evaluation.configuration.id,'uses configuration');
    const directSources=new Set(statement.evidence.map(e=>e.source.id));
    for(const [target,records,label] of [[evaluation.id,evaluation.evidence,'documents evaluation'],[evaluation.configuration.id,evaluation.configuration.evidence,'documents configuration']]){
      for(const evidence of records||[])if(!directSources.has(evidence.source.id)){
        node(evidence.source.id,evidence.source.label,'source');edge(evidence.source.id,target,label,evidence.id);
      }
    }
  }
  if (statement.supersedes) {
    const prior = payload.statements.find(s => s.id === statement.supersedes);
    if (prior) {
      node(prior.id,`Assertion r${prior.revision}\n${prior.lifecycle}`,'assertion');
      edge(statement.id,prior.id,'supersedes');
    }
  }
  return [...nodes.values(),...edges];
}

export function selectionExport(payload, rows) {
  return structuredClone({schema_version:1, release:payload.release,
    scope:'Selected qualified assertions and recorded evidence; no transitive support or independent reproduction inferred.',
    statements:rows});
}

export function neighborhoodLayout(elements, statementId, subjectId, width) {
  const nodes=elements.filter(e=>!e.data.source);
  const roots=nodes.filter(n=>n.data.id!==statementId &&
    (n.data.id===subjectId || ['source','evaluation'].includes(n.data.kind))).sort((a,b)=>a.data.id.localeCompare(b.data.id));
  const rootIds=new Set(roots.map(n=>n.data.id));
  const leaves=nodes.filter(n=>n.data.id!==statementId&&!rootIds.has(n.data.id)).sort((a,b)=>a.data.id.localeCompare(b.data.id));
  const positions={};let height=365;const narrow=width<600;
  if(narrow){
    const place=(items,start)=>items.forEach((n,i)=>{positions[n.data.id]={x:items.length===1?width/2:(i%2?width-68:68),y:start+Math.floor(i/2)*100};});
    place(roots,50);const center=50+Math.ceil(roots.length/2)*100;
    positions[statementId]={x:width/2,y:center};place(leaves,center+110);
    height=Math.max(365,center+110+Math.ceil(leaves.length/2)*100);
  }else{
    height=Math.max(365,Math.max(roots.length,leaves.length)*85+50);
    roots.forEach((n,i)=>{positions[n.data.id]={x:100,y:45+(i+.5)*((height-90)/roots.length)};});
    leaves.forEach((n,i)=>{positions[n.data.id]={x:width-100,y:45+(i+.5)*((height-90)/leaves.length)};});
    positions[statementId]={x:width/2,y:height/2};
  }
  return {positions,height,nodeWidth:narrow?112:170,fontSize:narrow?11:13};
}
